def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def identify_non_prime(numbers):
    non_prime_numbers = [num for num in numbers if not is_prime(num)]
